SELECT 'gongkao', '压力抗挫测试', 'kp-ms-match-pressure', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "自我认知：压力抗挫测试"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "面对压力不崩溃，面对批评不抱怨。展现心理韧性。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“你费了很大心血完成的报告，被领导当众批评一文不值，你怎么办？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、高分破题"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "情绪控制：坚决不辩解，坦然接受批评，并感谢领导的指正。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "反思内因：不要怪时间紧、不要怪同事不配合，只能怪自己“业务不精、考虑不周、没有领会领导意图”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "积极行动：会后立刻找领导请教修改意见，加班加点连夜重写，直到领导满意为止。"}]}]}]}]}$$ AS jsonb), NULL, '压力抗挫测试的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "自我认知", "抗压测试"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_match_pressure", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
